      spells_by_level: { 3: ["healing-word", "ray-of-frost"], 5: ["flaming-sphere", "melfs-acid-arrow"], 9: ["gaseous-form", "mass-healing-word"], 13: ["blight", "death-ward"], 17: ["cloudkill", "raise-dead"] },
